def _selection_target_model(self):
    return [
        (model.model, model.name)
        for model
        in self.env['ir.model'].sudo().search_fetch(
            [('transient', '=', False)], ['model', 'name']
        )
        if model.model in self.env
    ]

def _table_sql(self) -> SQL:
    today = fields.Date.today()
    query = self.env['sale.order.line'].sudo().with_context(date_to=today)._search(self._order_line_domain())
    query.groupby = SQL(", ").join(self._groupby_list(query.table))
    return query.subselect(*self._select_dict_to_list(self._select_dict(query.table)))

def action_open_order(self):

    order = self._get_order_reference()
    return order._get_records_action(context=clean_context(self.env.context))

def table_query(cls):
    from_item, tables, withs = cls._joins()
    return from_item.select(*cls._columns(tables, withs),
        where=cls._where(tables, withs),
        group_by=cls._group_by(tables, withs),
        with_=withs.values())

def _columns(cls, tables, withs):
    return super()._columns(tables, withs) + [
        cls._column_date(tables, withs).as_('date')]

def _group_by(cls, tables, withs):
    return super()._group_by(tables, withs) + [
        cls._column_date(tables, withs).as_('date')]

def _group_by(cls, tables, withs):
    party_category = tables['line.customer.party_category']
    return super()._group_by(tables, withs) + [party_category.category]

def table_query(cls):
    pool = Pool()
    Category = pool.get('party.category')
    return Category.__table__()

def _group_by(cls, tables, withs):
    template_category = tables['line.product.template_category']
    return super()._group_by(tables, withs) + [template_category.category]

def table_query(cls):
    pool = Pool()
    Category = pool.get('product.category')
    return Category.__table__()

def table_query(cls):
    pool = Pool()
    Region = pool.get('country.region')
    return Region.__table__()

def __setup__(cls):
    super().__setup__()
    cls._order.insert(0, ('country', 'ASC'))

def _column_id(cls, tables, withs):
    address = tables['line.shipment_address']
    return address.country

def time_series(self):
    record = self.union_unshard(self.id)
    return record.time_series

def transition_start(self):
    pool = Pool()
    Country = pool.get('sale.reporting.country')
    Subdivision = pool.get('sale.reporting.country.subdivision')
    record = self.model.union_unshard(self.record.id)
    if isinstance(record, Country):
        return 'country'
    elif isinstance(record, Subdivision):
        return 'subdivision'

def _do_action(self, action):
    record = self.model.union_unshard(self.record.id)
    data = {
        'id': record.id,
        'ids': [record.id],
        }
    action['name'] += ' (%s)' % record.rec_name
    return action, data

protected String prepareQuery(CrmReporting crmReporting, boolean isPartner, String model) {
  StringBuilder query = new StringBuilder();
  model = Strings.isNullOrEmpty(model) ? "" : model + ".";

  if (isPartner) {
    partnerQuery(query, crmReporting, model);
  } else {
    leadQuery(query, crmReporting, model);
  }

  if (!crmReporting.getAgencySet().isEmpty()
      && ((AppCrm) appBaseService.getApp("crm")).getAgenciesManagement())
    this.addParams(
        query,
        "self."
            + model
            + "agency.id IN ("
            + StringHelper.getIdListString(crmReporting.getAgencySet())
            + ")");

  if (!crmReporting.getIndustrySectorSet().isEmpty())
    this.addParams(
        query,
        "self."
            + model
            + "industrySector.id IN ("
            + StringHelper.getIdListString(crmReporting.getIndustrySectorSet())
            + ")");

  if (appBaseService.getAppBase().getTeamManagement() && !crmReporting.getTeamSet().isEmpty())
    this.addParams(
        query,
        "self.team.id IN (" + StringHelper.getIdListString(crmReporting.getTeamSet()) + ")");

  if (crmReporting.getFromDate() != null)
    this.addParams(query, "date(self.createdOn) >= :fromDate");

  if (crmReporting.getToDate() != null) this.addParams(query, "date(self.createdOn) <= :toDate");

  return query.toString();
}

private void partnerQuery(StringBuilder query, CrmReporting crmReporting, String model) {
  if (appBaseService.getAppBase().getEnableMultiCompany()
      && !crmReporting.getCompanySet().isEmpty())
    this.addParams(
        query,
        "(" + companyQuery("self." + model + "companySet", crmReporting.getCompanySet()) + ")");

  if (!crmReporting.getCategorySet().isEmpty())
    this.addParams(
        query,
        "self."
            + model
            + "partnerCategory.id "
            + "IN ("
            + StringHelper.getIdListString(crmReporting.getCategorySet())
            + ")");

  if (!crmReporting.getCountrySet().isEmpty())
    this.addParams(
        query,
        "self."
            + model
            + "partnerAddressList.address.country.id "
            + "IN ("
            + StringHelper.getIdListString(crmReporting.getCountrySet())
            + ")");
}

protected String companyQuery(String queryStr, Set<Company> companies) {
  return queryStr + ".id IN (" + StringHelper.getIdListString(companies) + ")";
}

def get_columns(self):
	self.columns = [
		{
			"label": _(self.filters.tree_type),
			"options": self.filters.tree_type if self.filters.tree_type != "Order Type" else "",
			"fieldname": "entity",
			"fieldtype": "Link" if self.filters.tree_type != "Order Type" else "Data",
			"width": 140 if self.filters.tree_type != "Order Type" else 200,
		}
	]
	if self.filters.tree_type in ["Customer", "Supplier", "Item"]:
		self.columns.append(
			{
				"label": _(self.filters.tree_type + " Name"),
				"fieldname": "entity_name",
				"fieldtype": "Data",
				"width": 140,
			}
		)

	if self.filters.tree_type == "Item":
		self.columns.append(
			{
				"label": _("UOM"),
				"fieldname": "stock_uom",
				"fieldtype": "Link",
				"options": "UOM",
				"width": 100,
			}
		)

	for end_date in self.periodic_daterange:
		period = self.get_period(end_date)
		self.columns.append(
			{"label": _(period), "fieldname": scrub(period), "fieldtype": "Float", "width": 120}
		)

	self.columns.append({"label": _("Total"), "fieldname": "total", "fieldtype": "Float", "width": 120})

def get_sales_transactions_based_on_customer_or_territory_group(self):
	if self.filters.tree_type == "Customer Group":
		entity_field = "customer_group as entity"
	elif self.filters.tree_type == "Supplier Group":
		entity_field = "supplier as entity"
		self.get_supplier_parent_child_map()
	else:
		entity_field = "territory as entity"

	self.entries = frappe.qb.get_query(
		table=self.filters.doc_type,
		fields=[entity_field, self.value_field, self.date_field],
		filters=self.document_filters,
		ignore_permissions=False,
	).run(as_dict=True)
	self.get_groups()

def get_groups(self):
	parent_field_map = {
		"Territory": "parent_territory",
		"Customer Group": "parent_customer_group",
		"Item Group": "parent_item_group",
		"Supplier Group": "parent_supplier_group",
	}
	if self.filters.tree_type not in parent_field_map:
		frappe.throw(_("Invalid Tree Type {0}").format(self.filters.tree_type))

	parent = parent_field_map[self.filters.tree_type]

	self.depth_map = frappe._dict()

	self.group_entries = frappe.db.sql(
		f"""select name, lft, rgt , {parent} as parent
		from `tab{self.filters.tree_type}` order by lft""",
		as_dict=1,
	)

	for d in self.group_entries:
		if d.parent:
			self.depth_map.setdefault(d.name, self.depth_map.get(d.parent) + 1)
		else:
			self.depth_map.setdefault(d.name, 0)

def get_chart_data(self):
	length = len(self.columns)

	if self.filters.tree_type in ["Customer", "Supplier"]:
		labels = [d.get("label") for d in self.columns[2 : length - 1]]
	elif self.filters.tree_type == "Item":
		labels = [d.get("label") for d in self.columns[3 : length - 1]]
	else:
		labels = [d.get("label") for d in self.columns[1 : length - 1]]

	datasets = []
	if self.filters.curves != "select":
		for curve in self.data:
			data = {
				"name": curve.get("entity_name", curve["entity"]),
				"values": [curve[scrub(label)] for label in labels],
			}
			if self.filters.curves == "non-zeros" and not sum(data["values"]):
				continue
			elif self.filters.curves == "total" and "indent" in curve:
				if curve["indent"] == 0:
					datasets.append(data)
			elif self.filters.curves == "total":
				if datasets:
					a = [
						data["values"][idx] + datasets[0]["values"][idx]
						for idx in range(len(data["values"]))
					]
					datasets[0]["values"] = a
				else:
					datasets.append(data)
					datasets[0]["name"] = _("Total")
			else:
				datasets.append(data)

	self.chart = {"data": {"labels": labels, "datasets": datasets}, "type": "line"}

	if self.filters["value_quantity"] == "Value":
		self.chart["fieldtype"] = "Currency"
	else:
		self.chart["fieldtype"] = "Float"

def setup_group_by(data):
	"""Add columns for aggregated values e.g. count(name)"""
	if data.group_by and data.aggregate_function:
		if data.aggregate_function.lower() not in ("count", "sum", "avg"):
			frappe.throw(_("Invalid aggregate function"))

		if frappe.db.has_column(data.aggregate_on_doctype, data.aggregate_on_field):
			field = f"`tab{data.aggregate_on_doctype}`.`{data.aggregate_on_field}`"
			data.fields.append({data.aggregate_function.upper(): field, "as": "_aggregate_column"})
		else:
			raise_invalid_field(data.aggregate_on_field)

		data.pop("aggregate_on_doctype")
		data.pop("aggregate_on_field")
		data.pop("aggregate_function")

def _validate_group_by_field(raw: str, doctype: str):
	"""Validate a single `tabDoctype`.`fieldname` expression from saved report JSON."""
	if not isinstance(raw, str) or not raw:
		raise_invalid_field(raw)
	try:
		field_doctype, fieldname = parse_field(raw)
	except ValueError:
		raise_invalid_field(raw)
	field_doctype = field_doctype or doctype
	if not _FIELDNAME_RE.match(fieldname):
		raise_invalid_field(raw)
	try:
		has_col = frappe.db.has_column(field_doctype, fieldname)
	except frappe.db.TableMissingError:
		raise_invalid_field(raw)
	if not has_col:
		raise_invalid_field(raw)

def _validate_group_by_args(group_by: dict, doctype: str):
	raw_func = group_by.get("aggregate_function")
	if not isinstance(raw_func, str):
		frappe.throw(_("Invalid aggregate function: {0}").format(raw_func), frappe.DataError)
	func = raw_func.lower()
	if func not in SUPPORTED_AGGREGATE_FUNCTIONS:
		frappe.throw(_("Invalid aggregate function: {0}").format(func), frappe.DataError)

	_validate_group_by_field(group_by.get("group_by", ""), doctype)

	if func != "count":
		_validate_group_by_field(group_by.get("aggregate_on", ""), doctype)

def save_report(name: str | int, doctype: str, report_settings: str):
	"""Save reports of type Report Builder from Report View"""

	if frappe.db.exists("Report", name):
		report = frappe.get_doc("Report", name)
		if report.is_standard == "Yes":
			frappe.throw(_("Standard Reports cannot be edited"))

		if report.report_type != "Report Builder":
			frappe.throw(_("Only reports of type Report Builder can be edited"))

		if report.owner != frappe.session.user and not report.has_permission("write"):
			frappe.throw(_("Insufficient Permissions for editing Report"), frappe.PermissionError)
	else:
		if not frappe.has_permission("Report", "create"):
			frappe.throw(_("You don't have permission to create Report records."), frappe.PermissionError)
		if not frappe.has_permission(doctype, "read"):
			frappe.throw(
				_("You don't have permission to create report for {0}").format(_(doctype)),
				frappe.PermissionError,
			)
		report = frappe.new_doc("Report")
		report.report_name = name
		report.ref_doctype = doctype

	settings = json.loads(report_settings)
	if isinstance(settings, dict) and isinstance(group_by := settings.get("group_by"), dict):
		_validate_group_by_args(group_by, report.ref_doctype)

	report.report_type = "Report Builder"
	report.json = report_settings
	report.save(ignore_permissions=True)
	frappe.msgprint(
		_("Report {0} saved").format(frappe.bold(report.name)),
		indicator="green",
		alert=True,
	)
	return report.name

def delete_report(name: str | int):
	"""Delete reports of type Report Builder from Report View"""

	report = frappe.get_doc("Report", name)
	if report.is_standard == "Yes":
		frappe.throw(_("Standard Reports cannot be deleted"))

	if report.report_type != "Report Builder":
		frappe.throw(_("Only reports of type Report Builder can be deleted"))

	if report.owner != frappe.session.user and not report.has_permission("delete"):
		frappe.throw(_("Insufficient Permissions for deleting Report"), frappe.PermissionError)

	report.delete(ignore_permissions=True)
	frappe.msgprint(
		_("Report {0} deleted").format(frappe.bold(report.name)),
		indicator="green",
		alert=True,
	)

def _export_query(form_params, csv_params, populate_response=True):
	from frappe.desk.utils import get_csv_bytes, provide_binary_file
	from frappe.utils.xlsxutils import get_default_xlsx_styles, handle_html, make_xlsx

	doctype = form_params.pop("doctype")
	owner_field = f"`tab{doctype}`.`owner`"
	if isinstance(form_params["fields"], list):
		form_params["fields"].append(owner_field)
	elif isinstance(form_params["fields"], tuple):
		form_params["fields"] = form_params["fields"] + (owner_field,)
	file_format_type = form_params.pop("file_format_type")
	title = form_params.pop("title", doctype)
	add_totals_row = 1 if form_params.pop("add_totals_row", None) == "1" else None
	translate_values = 1 if form_params.pop("translate_values", None) == "1" else None

	visible_names = form_params.pop("visible_names", None)
	if isinstance(visible_names, str):
		visible_names = frappe.parse_json(visible_names)
	if not (isinstance(visible_names, list) and visible_names):
		visible_names = None

	if selection := form_params.pop("selected_items", None):
		form_params["filters"] = {"name": ("in", json.loads(selection))}

	# visible_names is the client's ordered display sequence
	# When present, take precedence over generic filters/order/pagination: fetch
	# exactly those rows, then reorder in Python below.
	# Mirrors the visible_idx pattern in Query Report.
	if visible_names:
		form_params["filters"] = {"name": ("in", visible_names)}
		form_params["order_by"] = None
		form_params.pop("page_length", None)
		form_params.pop("limit_page_length", None)
		form_params.pop("start", None)

	make_access_log(
		doctype=doctype,
		file_type=file_format_type,
		report_name=form_params.report_name,
		filters=form_params.filters,
	)

	db_query = DatabaseQuery(doctype)
	ret = db_query.execute(**form_params)

	if visible_names:
		ret = _reorder_by_visible_names(ret, form_params.get("fields", []), doctype, visible_names)

	if not frappe.permissions.can_export(doctype):
		if frappe.permissions.can_export(doctype, is_owner=True):
			for row in ret:
				if row[-1] != frappe.session.user:
					raise frappe.PermissionError(
						_("You are not allowed to export {} doctype").format(doctype)
					)
		else:
			raise frappe.PermissionError(_("You are not allowed to export {} doctype").format(doctype))

	if add_totals_row:
		ret = append_totals_row(ret)

	fields_info = get_field_info(db_query.fields, doctype)

	labels = [info["label"] for info in fields_info]
	sr_label = _("Sr")
	data = [[sr_label, *labels]]
	processed_data = []

	if frappe.local.lang == "en" or not translate_values:
		data.extend([i + 1, *list(row)] for i, row in enumerate(ret))
	elif translate_values:
		translatable_fields = [field["translatable"] for field in fields_info]
		processed_data = []
		for i, row in enumerate(ret):
			processed_row = [i + 1] + [
				_(value) if translatable_fields[idx] else value for idx, value in enumerate(row)
			]
			processed_data.append(processed_row)
		data.extend(processed_data)

	data = handle_duration_fieldtype_values(doctype, data, db_query.fields)

	if file_format_type == "CSV":
		file_extension = "csv"
		content = get_csv_bytes(
			[[handle_html(v) if isinstance(v, str) else v for v in r] for r in data],
			csv_params,
		)
	elif file_format_type == "Excel":
		file_extension = "xlsx"

		styles = get_default_xlsx_styles(
			columns=[
				{
					"fieldname": "sr",
					"label": sr_label,
					"fieldtype": "Int",
				},
				*fields_info,
			],
			data=data[1:],  # exclude header row
			has_total_row=bool(add_totals_row),
		)

		content = make_xlsx(data, doctype, styles=styles).getvalue()

	if not populate_response:
		return title, file_extension, content

	provide_binary_file(_(title), file_extension, content)

def handle_duration_fieldtype_values(parent_doctype, data, fields):
	for field in fields:
		try:
			doctype, fieldname = parse_field(field)
		except ValueError:
			continue

		doctype = doctype or parent_doctype
		df = frappe.get_meta(doctype).get_field(fieldname)

		if df and df.fieldtype == "Duration":
			index = fields.index(field) + 1
			for i in range(1, len(data)):
				val_in_seconds = data[i][index]
				if val_in_seconds:
					duration_val = format_duration(val_in_seconds, df.hide_days)
					data[i][index] = duration_val
	return data
